insert into public.ai_knowledge(title,content,priority,is_active,status,source,topic) values
('Incline is OPEN — Enquiry Onboarding Sequence','[OPEN CLUB ENQUIRY FLOW] Incline is fully open and operating 24/7 at Sector 14, Udaipur (11,000 sq ft). There is NO founding membership, no reservation list, no waitlist and no launch date — never mention any of these. If someone asks about "founding memberships", warmly explain we are now open and they can join directly or visit the club. Flow for a new enquiry: 1) Welcome in one line and answer what they asked. 2) Ask their main fitness goal (strength, fat loss, recovery/wellness, general fitness). 3) Naturally collect name, then email, one at a time. 4) Ask which membership duration interests them (Monthly, Quarterly, Half-Yearly, Annual) — every duration is welcome, never discourage any. 5) Invite them for a club visit/tour as the next step, or to register online at https://theincline.in/register.',3,true,'active','manual','sales'),
('Personal Training — Enquiries','[PERSONAL TRAINING] Incline offers certified one-to-one personal training, Pilates and Yoga coaching. For leads: do not quote PT package names, session counts, prices or trainer names on chat; explain packages are tailored after a goal consultation and invite them to visit or speak with the team at the club. Existing members can check their PT sessions in the member portal at https://theincline.in/auth.',4,true,'active','manual','sales'),
('Pricing & Membership Protocol','[PRICING PROTOCOL] Do not quote prices, fees, GST or discounts over chat. Plans (Monthly, Quarterly, Half-Yearly, Annual) are tailored to goals and include options for recovery access, group classes and PT. Offer a club visit where the team walks them through the right plan in person, or share https://theincline.in/register to start online. Never refer to founding rates, pre-launch pricing or embargoes.',4,true,'active','manual','sales');